SELECT 
FROM TBL_PREDICTIVE_ANALYSIS


        AND ORGID = #{params.orgId}


        AND ANALYSISNO LIKE CONCAT('%', #{params.analysisNo}, '%')


        AND ANALYSISNAME LIKE CONCAT('%', #{params.analysisName}, '%')


        AND PREDICTIONTYPE = #{params.predictionType}


        AND MODELID = #{params.modelId}


        AND ANALYSISSTATUS = #{params.analysisStatus}


        AND PREDICTIONPERIOD = #{params.predictionPeriod}


        AND ANALYSISDATE >= #{params.startDate}


        AND ANALYSISDATE <= #{params.endDate}


        AND ACCURACY >= #{params.minAccuracy}


        AND ACCURACY <= #{params.maxAccuracy}


ORDER BY CREATETIME DESC

SELECT 
FROM TBL_PREDICTIVE_ANALYSIS
WHERE ANALYSISNO = #{analysisNo} AND ORGID = #{orgId}

SELECT COUNT(1)
FROM TBL_PREDICTIVE_ANALYSIS
WHERE ANALYSISNO = #{analysisNo} AND ORGID = #{orgId}

    AND ANALYSISID != #{excludeId}

SELECT 
FROM TBL_PREDICTIVE_ANALYSIS
WHERE ORGID = #{orgId}
AND ACCURACY >= #{minAccuracy}
AND ANALYSISSTATUS = 'COMPLETED'
ORDER BY ACCURACY DESC

mapper.update:
UPDATE TBL_PREDICTIVE_ANALYSIS
SET ANALYSISSTATUS = #{analysisStatus},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE ANALYSISID = #{analysisId}

UPDATE TBL_PREDICTIVE_ANALYSIS
SET PREDICTIONRESULT = #{predictionResult},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE ANALYSISID = #{analysisId}

UPDATE TBL_PREDICTIVE_ANALYSIS
SET ACTUALRESULT = #{actualResult},
    VALIDATIONDATE = CURRENT_DATE,
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE ANALYSISID = #{analysisId}

UPDATE TBL_PREDICTIVE_ANALYSIS
SET ACCURACY = #{accuracy},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE ANALYSISID = #{analysisId}

UPDATE TBL_PREDICTIVE_ANALYSIS
SET ANALYSISSTATUS = #{analysisStatus},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE ANALYSISID IN

    #{analysisId}

mapper.select:
SELECT COUNT(*) AS totalCount, COUNT(CASE WHEN ANALYSISSTATUS = 'PENDING' THEN 1 END) AS pendingCount, COUNT(CASE WHEN ANALYSISSTATUS = 'RUNNING' THEN 1 END) AS runningCount, COUNT(CASE WHEN ANALYSISSTATUS = 'COMPLETED' THEN 1 END) AS completedCount, COUNT(CASE WHEN ANALYSISSTATUS = 'FAILED' THEN 1 END) AS failedCount, AVG(ACCURACY) AS avgAccuracy, MAX(ACCURACY) AS maxAccuracy, MIN(ACCURACY) AS minAccuracy, COUNT(CASE WHEN ACCURACY >= 90 THEN 1 END) AS highAccuracyCount, COUNT(CASE WHEN ACCURACY >= 80 AND ACCURACY < 90 THEN 1 END) AS mediumAccuracyCount, COUNT(CASE WHEN ACCURACY < 80 THEN 1 END) AS lowAccuracyCount FROM TBL_PREDICTIVE_ANALYSIS WHERE ORGID = #{orgId}
AND ANALYSISDATE >= #{startDate}
AND ANALYSISDATE <= #{endDate}

SELECT
    ANALYSISDATE AS analysisDate,
    COUNT(*) AS analysisCount,
    AVG(ACCURACY) AS avgAccuracy,
    COUNT(CASE WHEN ANALYSISSTATUS = 'COMPLETED' THEN 1 END) AS completedCount
FROM TBL_PREDICTIVE_ANALYSIS
WHERE ORGID = #{orgId}

    AND PREDICTIONTYPE = #{predictionType}


    AND ANALYSISDATE >= #{startDate}


    AND ANALYSISDATE <= #{endDate}

GROUP BY ANALYSISDATE
ORDER BY ANALYSISDATE ASC

SELECT PREDICTIONTYPE AS predictionType, COUNT(*) AS totalPredictions, COUNT(CASE WHEN ANALYSISSTATUS = 'COMPLETED' THEN 1 END) AS completedPredictions, COUNT(CASE WHEN ANALYSISSTATUS = 'FAILED' THEN 1 END) AS failedPredictions, AVG(ACCURACY) AS avgAccuracy, AVG(PREDICTIONHORIZON) AS avgPredictionHorizon, COUNT(CASE WHEN ACTUALRESULT IS NOT NULL THEN 1 END) AS validatedPredictions FROM TBL_PREDICTIVE_ANALYSIS WHERE ORGID = #{orgId}
AND ANALYSISDATE >= #{startDate}
AND ANALYSISDATE <= #{endDate}
GROUP BY PREDICTIONTYPE ORDER BY avgAccuracy DESC

SELECT ANALYSISID AS analysisId, ANALYSISNO AS analysisNo, ANALYSISNAME AS analysisName, PREDICTIONTYPE AS predictionType, ACCURACY AS accuracy, ANALYSISDATE AS analysisDate, ANALYSISSTATUS AS analysisStatus FROM TBL_PREDICTIVE_ANALYSIS WHERE ANALYSISID IN
#{analysisId}
ORDER BY ACCURACY DESC

SELECT ANALYSISDATE AS analysisDate, ANALYSISNAME AS analysisName, ACCURACY AS accuracy, ANALYSISSTATUS AS analysisStatus, PREDICTIONHORIZON AS predictionHorizon FROM TBL_PREDICTIVE_ANALYSIS WHERE PREDICTIONTYPE = #{predictionType} AND ORGID = #{orgId}
AND ANALYSISDATE >= #{startDate}
AND ANALYSISDATE <= #{endDate}
ORDER BY ANALYSISDATE DESC

SELECT PREDICTIONTYPE AS predictionType, COUNT(CASE WHEN DEVIATIONANALYSIS IS NOT NULL THEN 1 END) AS deviationCount, AVG(ACCURACY) AS avgAccuracy, COUNT(*) AS totalCount FROM TBL_PREDICTIVE_ANALYSIS WHERE ORGID = #{orgId} AND ACTUALRESULT IS NOT NULL
AND VALIDATIONDATE >= #{startDate}
AND VALIDATIONDATE <= #{endDate}
GROUP BY PREDICTIONTYPE ORDER BY avgAccuracy DESC

SELECT PREDICTIONTYPE AS predictionType, COUNT(*) AS totalCount, AVG(ACCURACY) AS avgAccuracy, AVG(CONFIDENCELEVEL) AS avgConfidenceLevel, COUNT(CASE WHEN ACCURACY >= 85 THEN 1 END) AS highQualityCount, ROUND(COUNT(CASE WHEN ACCURACY >= 85 THEN 1 END) * 100.0 / COUNT(*), 2) AS qualityRate FROM TBL_PREDICTIVE_ANALYSIS WHERE ORGID = #{orgId} AND ANALYSISSTATUS = 'COMPLETED'
AND ANALYSISDATE >= #{startDate}
AND ANALYSISDATE <= #{endDate}
GROUP BY PREDICTIONTYPE ORDER BY qualityRate DESC
